1	//! Наборы фильтров касаний (`--set`, `FilterSet`), их артефакты (`SetPaths`),
2	//! контекст касания по семи осям (`CTX_AXES`, `Range`, `TouchContext`,
3	//! `touch_contexts`), режим по минутам (`RegimeDay`, `read_regime_day`) и
4	//! фильтр касаний в момент касания (`TouchFilter`) — общий для сигналов
5	//! сетки и замера ёмкости (`lob fill-capacity`). Вынесено из `bounce_grid`
6	//! при разрезке B3 (ревью 23.09), поведение не менялось.
7	
8	use std::collections::BTreeMap;
9	use std::path::{Path, PathBuf};
10	
11	use crate::book::Side;
12	use crate::lob::levels::{H3Mode, TouchRecord};
13	
14	use super::args::{BounceGridArgs, SideArg};
15	use super::cache::eaten_pct;
16	use super::drive::DayParams;
17	
18	/// Артефакты одного набора фильтров.
19	#[derive(Debug, Clone, Default, PartialEq, Eq)]
20	pub struct SetPaths {
21	    pub name: String,
22	    pub rounds_path: PathBuf,
23	    pub forms_path: PathBuf,
24	}
25	
26	/// Набор фильтров касаний одной сетки (`--set`, либо флаги команды).
27	#[derive(Debug, Clone, PartialEq)]
28	pub struct FilterSet {
29	    /// Имя подкаталога; пустое — артефакты в `<out-dir>` (без `--set`).
30	    pub name: String,
31	    pub frontrun_only: bool,
32	    pub min_age_secs: Option<i64>,
33	    pub min_flow_pct: Option<f64>,
34	    pub side: Option<SideArg>,
35	    /// Состояние стены при касании (S1 плана по сторонам, [D 33:57] «не
36	    /// заходить в разъедания»): доля съедания к касанию `100 × (1 −
37	    /// size_at_touch / size_max_before)` не больше этого процента. Только
38	    /// ключ набора `eaten=<%>`, флага у команды нет.
39	    pub eaten_max_pct: Option<f64>,
40	    /// T4 (П-02, Г-86, P-90 «огромный завал уже проедается»): доля съедания к
41	    /// касанию не меньше этого процента — зеркало `eaten_max_pct` (там «не
42	    /// больше», здесь «не меньше»), для условия входа рынком при сильном
43	    /// разъедании. Только ключ набора `eaten_min=<%>`.
44	    pub eaten_min_pct: Option<f64>,
45	    /// T-35 (Г-85, В-122): фронтран касания не меньше стольких лотов (`frontrun_min=<лоты>`) — сумма лотов той
46	    /// же стороны строго лучше уровня (`TouchRecord::frontrun_lots`, В-45); порог вместо «да/нет» `frontrun`.
47	    /// Только ключ набора.
48	    pub frontrun_min_lots: Option<i64>,
49	    /// Номинал стены при касании не меньше стольких долларов (`usd_min=`):
50	    /// ось «размер стены» поверх пола `--h3-usd` (стены ≥ пола — надмножество,
51	    /// так что ключ — подмножество тех же касаний).
52	    pub usd_min: Option<f64>,
53	    /// Контекст касания (S4): границы в bps по осям `CTX_AXES` — ход монеты
54	    /// до касания за 10 мин / 1 ч / 4 ч (`ret10m`, `ret1h`, `ret4h`; знак
55	    /// абсолютный), медиана пула за 1 ч / 4 ч (`pool1h`, `pool4h`) и биток
56	    /// (`btc1h`, `btc4h`, промежуточные `btc2h`, `btc3h` — E26); ключи
57	    /// `<ось>_min=` / `<ось>_max=`. Касание без
58	    /// значения оси при заданной границе выбывает.
59	    pub ctx: [Range; CTX_AXES.len()],
60	}
61	
62	/// Оси контекста касания — порядок общий для `FilterSet::ctx` и `TouchContext`.
63	/// `btc2h`/`btc3h` — в конце: индексы прежних осей не сдвигаются.
64	pub const CTX_AXES: [&str; 9] = [
65	    "ret10m", "ret1h", "ret4h", "pool1h", "pool4h", "btc1h", "btc4h", "btc2h", "btc3h",
66	];
67	
68	/// Границы одной оси контекста, bps; `None` — не задана.
69	#[derive(Debug, Clone, Copy, Default, PartialEq)]
70	pub struct Range {
71	    pub min: Option<f64>,
72	    pub max: Option<f64>,
73	}
74	
75	impl Range {
76	    pub(crate) fn is_set(self) -> bool {
77	        self.min.is_some() || self.max.is_some()
78	    }
79	
80	    pub(super) fn holds(self, v: Option<f64>) -> bool {
81	        if !self.is_set() {
82	            return true;
83	        }
84	        match v {
85	            None => false,
86	            Some(x) => self.min.is_none_or(|m| x >= m) && self.max.is_none_or(|m| x <= m),
87	        }
88	    }
89	}
90	
91	/// Контекст одного касания в порядке `CTX_AXES`; `None` — значения нет
92	/// (окно за началом записи, нет режима на минуту).
93	#[derive(Debug, Clone, Copy, Default, PartialEq)]
94	pub struct TouchContext {
95	    pub axes: [Option<f64>; CTX_AXES.len()],
96	}
97	
98	/// Режим суток по минутам из `regime.py`:
99	/// `minute_ms → (pool1h, pool4h, btc1h, btc4h, btc2h, btc3h)`.
100	pub(crate) type RegimeDay = BTreeMap<i64, [Option<f64>; 6]>;
101	
102	/// Колонки `btc_ret_2h_bps`/`btc_ret_3h_bps` пишет только `regime.py` после E26: в
103	/// прежних файлах их нет, и значения — `None`. Если оси нужны наборам (`need_mid`),
104	/// нет колонки — отказ (иначе все касания молча выбыли бы из набора).
105	pub(crate) fn read_regime_day(dir: &Path, day: &str, need_mid: bool) -> anyhow::Result<RegimeDay> {
106	    let path = dir.join(format!("{day}.csv"));
107	    let mut r = csv::ReaderBuilder::new()
108	        .from_path(&path)
109	        .map_err(|e| anyhow::anyhow!("--regime-from: {}: {e}", path.display()))?;
110	    let header = r.headers()?.clone();
111	    let idx = |name: &str| -> anyhow::Result<usize> {
112	        header
113	            .iter()
114	            .position(|h| h == name)
115	            .ok_or_else(|| anyhow::anyhow!("{}: нет колонки {name}", path.display()))
116	    };
117	    let opt = |name: &str| -> anyhow::Result<Option<usize>> {
118	        match header.iter().position(|h| h == name) {
119	            Some(i) => Ok(Some(i)),
120	            None if need_mid => anyhow::bail!(
121	                "{}: нет колонки {name} — оси btc2h/btc3h требуют режим, пересчитанный regime.py",
122	                path.display()
123	            ),
124	            None => Ok(None),
125	        }
126	    };
127	    let cols = [
128	        Some(idx("minute_ms")?),
129	        Some(idx("pool_ret_1h_bps")?),
130	        Some(idx("pool_ret_4h_bps")?),
131	        Some(idx("btc_ret_1h_bps")?),
132	        Some(idx("btc_ret_4h_bps")?),
133	        opt("btc_ret_2h_bps")?,
134	        opt("btc_ret_3h_bps")?,
135	    ];
136	    let mut out = RegimeDay::new();
137	    for rec in r.records() {
138	        let rec = rec?;
139	        let minute: i64 = rec
140	            .get(cols[0].expect("minute_ms обязателен"))
141	            .ok_or_else(|| anyhow::anyhow!("{}: короткая строка", path.display()))?
142	            .parse()?;
143	        let mut vals = [None; 6];
144	        for (k, c) in cols[1..].iter().enumerate() {
145	            let Some(c) = c else { continue };
146	            let v = rec.get(*c).unwrap_or("");
147	            vals[k] = if v.is_empty() {
148	                None
149	            } else {
150	                Some(v.parse::<f64>()?)
151	            };
152	        }
153	        out.insert(minute, vals);
154	    }
155	    Ok(out)
156	}
157	
158	/// Контекст касаний суток: ход монеты — из кэша (`TouchRow::ret_bps`) или из
159	/// реплея (`pre_touch_return_bps_csv` — те же шесть знаков), режим — по
160	/// минуте `start_ms` из `RegimeDay` (нет режима — `None`).
161	pub(crate) fn touch_contexts(
162	    rets: &[[Option<f64>; 3]],
163	    touches: &[TouchRecord],
164	    regime: Option<&RegimeDay>,
165	) -> Vec<TouchContext> {
166	    debug_assert_eq!(rets.len(), touches.len());
167	    touches
168	        .iter()
169	        .zip(rets)
170	        .map(|(t, r)| {
171	            let minute = t.start_ms - t.start_ms.rem_euclid(60_000);
172	            let m = regime
173	                .and_then(|g| g.get(&minute))
174	                .copied()
175	                .unwrap_or([None; 6]);
176	            TouchContext {
177	                axes: [r[0], r[1], r[2], m[0], m[1], m[2], m[3], m[4], m[5]],
178	            }
179	        })
180	        .collect()
181	}
182	
183	impl FilterSet {
184	    /// Хоть один ключ контекста задан.
185	    pub(super) fn uses_ctx(&self) -> bool {
186	        self.ctx.iter().any(|r| r.is_set())
187	    }
188	
189	    /// Хоть один ключ режима (`pool*`/`btc*`) задан — нужен `--regime-from`.
190	    pub(crate) fn uses_regime(&self) -> bool {
191	        self.ctx[3..].iter().any(|r| r.is_set())
192	    }
193	
194	    /// Хоть один ключ промежуточных осей битка (`btc2h`/`btc3h`) задан — в файлах
195	    /// режима нужны их колонки (`read_regime_day`, `need_mid`).
196	    pub(crate) fn uses_btc_mid(&self) -> bool {
197	        self.ctx[7..].iter().any(|r| r.is_set())
198	    }
199	
200	    /// Хоть один ключ хода **монеты** до сигнала (`ret10m`/`ret1h`/`ret4h`)
201	    /// задан — их несёт только кэш касаний (`TouchRow::ret_bps`).
202	    pub(crate) fn uses_ret(&self) -> bool {
203	        self.ctx[..3].iter().any(|r| r.is_set())
204	    }
205	
206	    /// Ключи контекста набора для шапки: `ret1h_min=… pool4h_max=…`.
207	    pub(super) fn ctx_label(&self) -> String {
208	        let mut parts = Vec::new();
209	        for (name, r) in CTX_AXES.iter().zip(&self.ctx) {
210	            if let Some(v) = r.min {
211	                parts.push(format!("{name}_min={v}"));
212	            }
213	            if let Some(v) = r.max {
214	                parts.push(format!("{name}_max={v}"));
215	            }
216	        }
217	        if parts.is_empty() {
218	            "none".to_string()
219	        } else {
220	            parts.join(",")
221	        }
222	    }
223	
224	    pub(super) fn from_args(args: &BounceGridArgs) -> Self {
225	        Self {
226	            name: String::new(),
227	            frontrun_only: args.frontrun_only,
228	            min_age_secs: args.min_age_secs,
229	            min_flow_pct: args.min_flow_pct,
230	            side: args.side,
231	            eaten_max_pct: None,
232	            eaten_min_pct: None,
233	            frontrun_min_lots: None,
234	            usd_min: None,
235	            ctx: [Range::default(); CTX_AXES.len()],
236	        }
237	    }
238	
239	    /// `<имя>:<k=v,…>` — см. `BounceGridArgs::sets`. Повтор ключа и чужой
240	    /// ключ — отказ: набор пишется один раз и читается людьми.
241	    pub fn parse(spec: &str) -> anyhow::Result<Self> {
242	        let (name, rest) = spec
243	            .split_once(':')
244	            .ok_or_else(|| anyhow::anyhow!("--set {spec:?}: ожидается <имя>:<k=v,…>"))?;
245	        anyhow::ensure!(
246	            !name.is_empty()
247	                && name
248	                    .chars()
249	                    .all(|c| c.is_ascii_alphanumeric() || matches!(c, '.' | '_' | '-'))
250	                && name != "."
251	                && name != "..",
252	            "--set {spec:?}: имя набора — буквы, цифры, `.`, `_`, `-`"
253	        );
254	        let mut set = Self {
255	            name: name.to_string(),
256	            frontrun_only: false,
257	            min_age_secs: None,
258	            min_flow_pct: None,
259	            side: None,
260	            eaten_max_pct: None,
261	            eaten_min_pct: None,
262	            frontrun_min_lots: None,
263	            usd_min: None,
264	            ctx: [Range::default(); CTX_AXES.len()],
265	        };
266	        let mut seen = std::collections::BTreeSet::new();
267	        for kv in rest.split(',').filter(|s| !s.is_empty()) {
268	            let (k, v) = kv.split_once('=').unwrap_or((kv, ""));
269	            anyhow::ensure!(
270	                seen.insert(k.to_string()),
271	                "--set {spec:?}: ключ {k} повторяется"
272	            );
273	            match k {
274	                "age" => {
275	                    set.min_age_secs = Some(
276	                        v.parse()
277	                            .map_err(|e| anyhow::anyhow!("--set {spec:?}: age={v:?}: {e}"))?,
278	                    );
279	                }
280	                "flow" => {
281	                    set.min_flow_pct = Some(
282	                        v.parse()
283	                            .map_err(|e| anyhow::anyhow!("--set {spec:?}: flow={v:?}: {e}"))?,
284	                    );
285	                }
286	                "side" => {
287	                    set.side = Some(match v {
288	                        "bid" => SideArg::Bid,
289	                        "ask" => SideArg::Ask,
290	                        _ => anyhow::bail!("--set {spec:?}: side={v:?}, ожидается bid|ask"),
291	                    });
292	                }
293	                "usd_min" => {
294	                    let usd: f64 = v
295	                        .parse()
296	                        .map_err(|e| anyhow::anyhow!("--set {spec:?}: usd_min={v:?}: {e}"))?;
297	                    anyhow::ensure!(
298	                        usd.is_finite() && usd >= 0.0,
299	                        "--set {spec:?}: usd_min={v:?} — доллары обязаны быть неотрицательным числом"
300	                    );
301	                    set.usd_min = Some(usd);
302	                }
303	                "eaten" => {
304	                    let pct: f64 = v
305	                        .parse()
306	                        .map_err(|e| anyhow::anyhow!("--set {spec:?}: eaten={v:?}: {e}"))?;
307	                    anyhow::ensure!(
308	                        pct.is_finite(),
309	                        "--set {spec:?}: eaten={v:?} — процент обязан быть числом"
310	                    );
311	                    set.eaten_max_pct = Some(pct);
312	                }
313	                "eaten_min" => {
314	                    let pct: f64 = v
315	                        .parse()
316	                        .map_err(|e| anyhow::anyhow!("--set {spec:?}: eaten_min={v:?}: {e}"))?;
317	                    anyhow::ensure!(
318	                        pct.is_finite(),
319	                        "--set {spec:?}: eaten_min={v:?} — процент обязан быть числом"
320	                    );
321	                    set.eaten_min_pct = Some(pct);
322	                }
323	                "frontrun_min" => {
324	                    let n: i64 = v
325	                        .parse()
326	                        .map_err(|e| anyhow::anyhow!("--set {spec:?}: frontrun_min={v:?}: {e}"))?;
327	                    anyhow::ensure!(
328	                        n >= 1,
329	                        "--set {spec:?}: frontrun_min={v:?} — целое число лотов ≥ 1"
330	                    );
331	                    set.frontrun_min_lots = Some(n);
332	                }
333	                "frontrun" => {
334	                    anyhow::ensure!(
335	                        v.is_empty() || v == "1" || v == "true",
336	                        "--set {spec:?}: frontrun без значения (или =1)"
337	                    );
338	                    set.frontrun_only = true;
339	                }
340	                _ => {
341	                    let (axis, bound) = k
342	                        .rsplit_once('_')
343	                        .ok_or_else(|| anyhow::anyhow!("--set {spec:?}: неизвестный ключ {k:?} (age|flow|side|frontrun|frontrun_min|eaten|eaten_min|usd_min|<ось>_min|<ось>_max)"))?;
344	                    let i = CTX_AXES.iter().position(|a| *a == axis).ok_or_else(|| {
345	                        anyhow::anyhow!("--set {spec:?}: неизвестная ось {axis:?} (ret10m|ret1h|ret4h|pool1h|pool4h|btc1h|btc4h|btc2h|btc3h)")
346	                    })?;
347	                    let v: f64 = v
348	                        .parse()
349	                        .map_err(|e| anyhow::anyhow!("--set {spec:?}: {k}={v:?}: {e}"))?;
350	                    anyhow::ensure!(
351	                        v.is_finite(),
352	                        "--set {spec:?}: {k}={v:?} — bps обязаны быть числом"
353	                    );
354	                    match bound {
355	                        "min" => set.ctx[i].min = Some(v),
356	                        "max" => set.ctx[i].max = Some(v),
357	                        _ => anyhow::bail!(
358	                            "--set {spec:?}: {k:?} — ожидается <ось>_min или <ось>_max"
359	                        ),
360	                    }
361	                }
362	            }
363	        }
364	        Ok(set)
365	    }
366	}
367	
368	/// Фильтр касаний набора в момент касания — один и тот же для сигналов сетки
369	/// (`signals_for`) и для замера ёмкости (`lob fill-capacity`, S10): порог
370	/// плотности, фронтран, возраст, сила «×поток», сторона, съедание, номинал,
371	/// контекст. Касание, не прошедшее фильтр, — «пропуск» у вызывающего.
372	pub(crate) struct TouchFilter<'a> {
373	    pub(crate) tick: f64,
374	    pub(crate) lot: f64,
375	    pub(crate) frontrun_only: bool,
376	    pub(crate) mode: H3Mode,
377	    pub(crate) min_age_ms: Option<i64>,
378	    pub(crate) min_flow_pct: Option<f64>,
379	    pub(crate) side: Option<Side>,
380	    pub(crate) eaten_max_pct: Option<f64>,
381	    pub(crate) eaten_min_pct: Option<f64>,
382	    pub(crate) frontrun_min_lots: Option<i64>,
383	    pub(crate) usd_min: Option<f64>,
384	    pub(crate) ctx: Option<&'a [TouchContext]>,
385	    pub(crate) ctx_ranges: [Range; CTX_AXES.len()],
386	}
387	
388	impl<'a> TouchFilter<'a> {
389	    pub(super) fn from_day(p: &DayParams<'a>) -> Self {
390	        Self {
391	            tick: p.tick,
392	            lot: p.lot,
393	            frontrun_only: p.frontrun_only,
394	            mode: p.mode,
395	            min_age_ms: p.min_age_ms,
396	            min_flow_pct: p.min_flow_pct,
397	            side: p.side,
398	            eaten_max_pct: p.eaten_max_pct,
399	            eaten_min_pct: p.eaten_min_pct,
400	            frontrun_min_lots: p.frontrun_min_lots,
401	            usd_min: p.usd_min,
402	            ctx: p.ctx,
403	            ctx_ranges: p.ctx_ranges,
404	        }
405	    }
406	
407	    /// Фильтр набора над касаниями суток с готовым контекстом (`touch_contexts`):
408	    /// контекст подаётся, только если у набора есть ключи контекста.
409	    pub(crate) fn from_set(
410	        set: &FilterSet,
411	        mode: H3Mode,
412	        tick: f64,
413	        lot: f64,
414	        ctx: &'a [TouchContext],
415	    ) -> Self {
416	        Self {
417	            tick,
418	            lot,
419	            frontrun_only: set.frontrun_only,
420	            mode,
421	            min_age_ms: set.min_age_secs.map(|s| s.saturating_mul(1_000)),
422	            min_flow_pct: set.min_flow_pct,
423	            side: set.side.map(Side::from),
424	            eaten_max_pct: set.eaten_max_pct,
425	            eaten_min_pct: set.eaten_min_pct,
426	            frontrun_min_lots: set.frontrun_min_lots,
427	            usd_min: set.usd_min,
428	            ctx: if set.uses_ctx() { Some(ctx) } else { None },
429	            ctx_ranges: set.ctx,
430	        }
431	    }
432	
433	    /// Проходит ли касание `t` с индексом `ti` (индекс — в контекст суток).
434	    #[allow(clippy::cast_precision_loss)]
435	    pub(crate) fn admits(&self, ti: usize, t: &TouchRecord) -> bool {
436	        if self.frontrun_only && t.frontrun_tick.is_none() {
437	            return false;
438	        }
439	        if self.frontrun_min_lots.is_some_and(|n| t.frontrun_lots < n) {
440	            return false;
441	        }
442	        // База E1 (В-66): плотность обязана держать порог при подходе цены,
443	        // а не только при рождении — иначе в сетку идут касания
444	        // «бывших» плотностей. Окно проверено при старте прогона.
445	        if self.mode.holds_at_touch(t) != Some(true) {
446	            return false;
447	        }
448	        if self.min_age_ms.is_some_and(|n| t.age_ms() < n) {
449	            return false;
450	        }
451	        if let Some(s_min) = self.min_flow_pct {
452	            let flow_ok = t.flow_1h_lots > 0
453	                && t.size_at_touch as f64 / t.flow_1h_lots as f64 * 100.0 >= s_min;
454	            if !flow_ok {
455	                return false;
